const $=s=>document.querySelector(s);
const esc=x=>String(x??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const yen=n=>'¥'+Math.round(Number(n)||0).toLocaleString('ja-JP');
const uid=()=>globalThis.crypto?.randomUUID?.()||'id-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
const localISO=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');
const today=()=>localISO(new Date());
const dateFmt=d=>{if(!d)return '日付未設定';let t=new Date(d+'T12:00:00');return Number.isNaN(t.getTime())?d:t.toLocaleDateString('ja-JP',{month:'long',day:'numeric',weekday:'short'});};
const fullDate=d=>{if(!d)return '';let t=new Date(d+'T12:00:00');return Number.isNaN(t.getTime())?d:t.toLocaleDateString('ja-JP',{year:'numeric',month:'long',day:'numeric',weekday:'short'});};
const dateRange=(a,b)=>{let from=new Date((a||today())+'T12:00:00'),to=new Date((b||a||today())+'T12:00:00');let out=[];for(let i=0;i<80&&from<=to;i++){out.push(localISO(from));from.setDate(from.getDate()+1);}return out.length?out:[a||today()];};
const catIcons={観光:'🏛️',移動:'🚆',食事:'🍽️',宿泊:'🏨',買い物:'🛍️',休憩:'☕',その他:'✦',交通:'🚆',宿泊費:'🏨',食費:'🍜',体験:'🎟️',お土産:'🎁'};
const categories=['観光','移動','食事','宿泊','買い物','休憩','その他'];
const feeCategories=['交通','宿泊費','食費','体験','お土産','その他'];
