function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('tabi-techo-db',1);r.onupgradeneeded=()=>{r.result.createObjectStore('store');};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
let dbPromise;
async function load(){try{dbPromise=openDB();const db=await dbPromise;const value=await new Promise((resolve,reject)=>{let t=db.transaction('store','readonly').objectStore('store').get('app');t.onsuccess=()=>resolve(t.result);t.onerror=()=>reject(t.error);});if(value?.trips&&Array.isArray(value.trips))state=value;}catch(e){storageOk=false;console.warn('IndexedDB利用不可:',e);toast('保存領域を利用できません。データの保持に注意してください。');}}
let saveQueue=Promise.resolve();function persist(){if(!storageOk)return;const snapshot=structuredClone(state);saveQueue=saveQueue.catch(()=>{}).then(async()=>{const db=await dbPromise;await new Promise((resolve,reject)=>{const tx=db.transaction('store','readwrite');tx.objectStore('store').put(snapshot,'app');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}).catch(e=>{console.error(e);toast('保存に失敗しました。容量をご確認ください。');});}
function changed(message){persist();render();if(message)toast(message);}
function toast(msg){let el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
function showDialog(title,body,foot=''){dialogBody.innerHTML=`<div class="dialog-inner"><div class="dialog-header"><div><div class="eyebrow">TABI NO TECHO</div><h2 class="dialog-title">${esc(title)}</h2></div><button class="btn btn-ghost btn-icon" type="button" data-act="close-dialog" aria-label="閉じる">✕</button></div>${body}${foot}</div>`;dialog.showModal();dialog.scrollTop=0;}
function closeDialog(){if(dialog.open)dialog.close();dialogBody.innerHTML='';}
function bindForm(id,fn){const f=$('#'+id);if(!f)return;f.addEventListener('submit',async e=>{e.preventDefault();const btn=f.querySelector('button[type="submit"]');if(btn)btn.disabled=true;try{await fn(new FormData(f),f);}catch(err){console.error(err);toast(err?.message||'処理中に問題が発生しました。');}finally{if(btn&&btn.isConnected)btn.disabled=false;}});}
function field(label,name,type='text',value='',opts={}){let req=opts.required?'required':'';let add=opts.attrs||'';const cls=opts.span?' span2':'';const min=opts.min!==undefined?`min="${opts.min}"`:'';return `<div class="form-field${cls}"><label for="field-${esc(name)}">${esc(label)}</label><input id="field-${esc(name)}" name="${esc(name)}" type="${esc(type)}" value="${esc(value)}" ${req} ${min} ${add}>${opts.help?`<div class="form-help">${esc(opts.help)}</div>`:''}</div>`;}
function textarea(label,name,value='',span=true){return `<div class="form-field${span?' span2':''}"><label for="field-${esc(name)}">${esc(label)}</label><textarea id="field-${esc(name)}" name="${esc(name)}">${esc(value)}</textarea></div>`;}
function selectField(label,name,items,value='',span=false){return `<div class="form-field${span?' span2':''}"><label for="field-${esc(name)}">${esc(label)}</label><select name="${esc(name)}" id="field-${esc(name)}">${items.map(it=>`<option value="${esc(it)}" ${value===it?'selected':''}>${esc(it)}</option>`).join('')}</select></div>`;}
function buttons(submit='保存する',extra=''){return `<div class="dialog-actions">${extra}<button type="button" class="btn btn-ghost" data-act="close-dialog">キャンセル</button><button class="btn btn-primary" type="submit">${esc(submit)}</button></div>`;}
async function compress(file,max=1400,quality=.83){if(!file)return '';if(!file.type.startsWith('image/'))throw Error('画像ファイルを選択してください。');if(file.size>30*1024*1024)throw Error('画像が大きすぎます（30MB以下）。');const url=URL.createObjectURL(file);try{const img=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(Error('画像を読み込めませんでした。JPEG・PNGなどをお試しください。'));i.src=url;});const w=img.naturalWidth||img.width,h=img.naturalHeight||img.height;const factor=Math.min(1,max/Math.max(w,h));const cv=document.createElement('canvas');cv.width=Math.max(1,Math.round(w*factor));cv.height=Math.max(1,Math.round(h*factor));const c=cv.getContext('2d');c.fillStyle='#fff';c.fillRect(0,0,cv.width,cv.height);c.drawImage(img,0,0,cv.width,cv.height);return cv.toDataURL('image/jpeg',quality);}finally{URL.revokeObjectURL(url);}}
function download(blob,name){let url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function fileSafe(s){return String(s||'旅の手帖').replace(/[\\/:*?"<>|\s]/g,'_').slice(0,35);}
