function sample(){let t=newTrip({title:'北海道の小さな冒険（サンプル）',destination:'札幌・小樽・富良野',description:'この旅行は操作を試すためのサンプルです。自由に編集・削除できます。',start:'2027-02-12',end:'2027-02-14',budget:80000});t.members.push({id:uid(),name:'旅の仲間',color:'#c69b63'});const add=(date,time,name,cat,place,cost)=>t.schedules.push({id:uid(),date,time,endTime:'',name,category:cat,place,notes:'',address:'',url:'',planCost:cost,photo:'',status:'pending',showBoard:true});add('2027-02-12','09:30','札幌時計台を見学','観光','札幌時計台',400);add('2027-02-12','11:30','北海道グルメを楽しむ','食事','札幌市内',4000);add('2027-02-12','14:00','小樽運河を散策','観光','小樽運河',0);add('2027-02-12','18:00','宿にチェックイン','宿泊','小樽市内',20000);add('2027-02-13','09:00','富良野へ移動','移動','富良野',5000);add('2027-02-13','12:30','丘の景色を見に行く','観光','富良野',1000);add('2027-02-13','17:00','夕食と休憩','食事','富良野',5000);add('2027-02-14','10:00','羊蹄山の景色を楽しむ','観光','ニセコ',0);add('2027-02-14','15:00','帰路へ','移動','札幌',5000);t.packing=[{id:uid(),text:'充電器',done:false},{id:uid(),text:'防寒着',done:false},{id:uid(),text:'予約確認',done:false}];return t;}
