function renderNavigation(){const items=navItems();$('#sidebar').innerHTML=`<div class="brand"><div class="brand-mark">✦</div><div><div class="brand-title">旅の手帖</div><div class="brand-desc">旅を、一冊の物語に。</div></div></div><div class="nav-label">MAIN MENU</div><div class="side-nav">${items.map(n=>`<button class="nav-btn ${ui.screen===n.id?'active':''}" data-act="nav" data-screen="${n.id}"><span class="symbol">${n.icon}</span>${n.label}</button>`).join('')}<button class="nav-btn ${ui.screen==='settings'?'active':''}" data-act="nav" data-screen="settings"><span class="symbol">⚙</span>設定・バックアップ</button></div><div class="sidebar-bottom"><b>旅の手帖</b><br><span class="muted small">予定も、思い出も、あなたの手元に。<br>端末内に自動保存します。</span></div>`;$('#bottom-nav').innerHTML=items.map(n=>`<button class="bottom-link ${ui.screen===n.id?'active':''}" data-act="nav" data-screen="${n.id}"><span class="symbol">${n.icon}</span><span>${n.label}</span></button>`).join('');}
function renderTop(){let trip=current();$('#topbar').innerHTML=`<div><div class="topbar-title">旅の手帖 <span style="color:var(--gold)">✦</span></div><div class="topbar-caption">PLAN · EXPLORE · REMEMBER</div></div><div class="row"><select class="trip-select" id="trip-switch" aria-label="旅行を切り替える"><option value="">旅行を選択</option>${state.trips.map(t=>`<option value="${esc(t.id)}" ${t.id===ui.tripId?'selected':''}>${esc(t.title)}</option>`).join('')}</select><button data-act="new-trip" class="btn btn-primary btn-sm" title="旅行を作成">＋ <span class="hide-small">新しい旅</span></button></div>`;}
function heading(label,title,description,buttons=''){return `<div class="page-heading"><div><div class="eyebrow">${esc(label)}</div><h1 class="page-title">${esc(title)}</h1><p class="page-description">${esc(description)}</p></div>${buttons?`<div class="btn-row">${buttons}</div>`:''}</div>`;}
