function renderHome(){const n=state.trips.length;return `${heading('WELCOME TO YOUR JOURNEY','次の旅を、物語に。','旅の計画から、すごろくの冒険、思い出の一冊まで。')}<div class="home-hero"><div class="content"><div class="eyebrow" style="color:#e8d4a3">YOUR LITTLE TRAVEL COMPANION</div><div class="hero-title serif">まだ見ぬ景色へ。<br>旅の一歩を、ここから。</div><p class="hero-sub">予定を並べ、予算を整え、冒険マップを作る。<br>帰ってきたら、写真を一冊の思い出に。</p><button class="btn hero-btn" data-act="new-trip">✦ 新しい旅を作る</button></div></div><div class="section-header"><h2 class="section-title">旅の本棚 <span class="muted small">${n}冊</span></h2>${n?`<button class="btn btn-ghost btn-sm" data-act="sample">＋ サンプルを追加</button>`:''}</div>${n?`<div class="trip-cards">${state.trips.slice().sort((a,b)=>b.start.localeCompare(a.start)).map(t=>`<article class="trip-card" data-act="open-trip" data-id="${esc(t.id)}" tabindex="0" role="button"><div class="trip-cover">${imageSrc(t.cover)?`<img src="${imageSrc(t.cover)}" alt="旅行の表紙">`:''}<div class="cover-text">✦</div></div><div class="trip-card-body"><span class="tag ${today()>t.end?'gray':today()>=t.start?'orange':''}">${today()>t.end?'旅の記録':today()>=t.start?'旅行中':'計画中'}</span><h3 class="trip-card-title">${esc(t.title)}</h3><div class="trip-metas">📅 ${esc(dateFmt(t.start))} 〜 ${esc(dateFmt(t.end))}<br>📍 ${esc(t.destination||'行き先未設定')}　・ ${t.schedules.length}件の予定</div><div class="row between mt16"><span class="small subtle">旅を開く</span><span style="color:var(--forest)">→</span></div></div></article>`).join('')}</div>`:`<div class="empty"><div class="empty-art">📖</div><h3>旅の本棚は、まだ空っぽ。</h3><p>最初の旅を作るか、サンプルで操作を試してみてください。</p><div class="btn-row" style="justify-content:center"><button class="btn btn-primary" data-act="new-trip">＋ 旅を作る</button><button class="btn btn-ghost" data-act="sample">サンプル旅行を試す</button></div></div>`}<div class="section-header"><h2 class="section-title">旅の手帖でできること</h2></div><div class="grid3">${[['▤','しおりを作る','時刻・予定・写真を並べて、A4縦のPDFに。'],['🎲','すごろくで楽しむ','旅程をRPG風の冒険マップで表現。'],['▧','思い出を残す','旅先の写真をまとめてアルバムPDFに。']].map(([i,t,d])=>`<div class="panel"><div style="font-size:27px;margin-bottom:13px">${i}</div><b>${t}</b><p class="small muted" style="line-height:1.7;margin:8px 0 0">${d}</p></div>`).join('')}</div>`;}
function tripBanner(t){return `<div class="trip-banner"><div><div class="eyebrow">CURRENT JOURNEY</div><h3>${esc(t.title)}</h3><div class="small subtle">${esc(dateFmt(t.start))} 〜 ${esc(dateFmt(t.end))} ・ ${esc(t.destination||'行き先未設定')}</div></div><button class="btn btn-ghost btn-sm" data-act="edit-trip">⚙ 旅の設定</button></div>`;}
function renderSchedule(t){const days=dateRange(t.start,t.end),day=selectedDay(t),items=orderSched(t).filter(s=>s.date===day),planned=sum(t.schedules,'planCost');const tab=days.map((d,i)=>`<button class="tab ${d===day?'active':''}" data-act="day" data-date="${d}"><div class="small">DAY ${i+1}</div>${esc(dateFmt(d))}</button>`).join('');return `${heading('TRAVEL ITINERARY','旅のしおり','予定を追加すると、すごろくにも自動で反映されます。',`<button class="btn btn-secondary btn-sm" data-act="pdf-itinerary">↓ A4 PDF</button>`)}${tripBanner(t)}<div class="grid3"><div class="kpi"><div class="label">登録した予定</div><div class="num">${t.schedules.length}<span class="small"> 件</span></div><div class="aside">全日程</div></div><div class="kpi"><div class="label">旅行日数</div><div class="num">${days.length}<span class="small"> 日</span></div><div class="aside">${esc(dateFmt(t.start))} 発</div></div><div class="kpi"><div class="label">予定費用の合計</div><div class="num">${yen(planned)}</div><div class="aside">登録した予定から計算</div></div></div><div class="section-header"><h2 class="section-title">日ごとのスケジュール</h2><button class="btn btn-primary btn-sm" data-act="new-sched">＋ 予定を追加</button></div><div class="tabs" role="tablist">${tab}</div><div class="day-heading"><h3>${esc(fullDate(day))}</h3><span class="tag">${items.length}件の予定</span></div>${items.length?`<div class="schedule-list">${items.map(s=>`<div class="sched-row" data-act="edit-sched" data-id="${esc(s.id)}" role="button" tabindex="0"><div class="sched-time">${esc(s.time)}<small>${esc(s.endTime?`〜${s.endTime}`:'')}</small></div><div class="sched-info"><div class="row wrap" style="gap:6px;margin-bottom:5px"><span class="tag ${s.status==='visited'?'orange':''}">${s.status==='visited'?'✓ 訪問済み':esc(s.category||'予定')}</span>${Number(s.planCost)?`<span class="small muted">${yen(s.planCost)}</span>`:''}</div><div class="sched-name">${esc(s.name)}</div><div class="sched-note">${esc(s.place||s.notes||'詳細をタップして編集')}</div></div><div class="sched-thumb">${imageSrc(s.photo)?`<img src="${imageSrc(s.photo)}" alt="${esc(s.name)}">`:esc(catIcons[s.category]||'📌')}</div></div>`).join('')}</div>`:`<div class="empty"><div class="empty-art">🗓️</div><h3>この日の予定を登録しましょう</h3><p>時刻・予定名・写真を登録すると、しおりが完成していきます。</p><button class="btn btn-primary" data-act="new-sched">＋ 最初の予定を追加</button></div>`}<div class="section-header"><h2 class="section-title">旅の準備</h2><button class="btn btn-ghost btn-sm" data-act="add-packing">＋ 持ち物</button></div><div class="grid2"><div class="panel"><b>持ち物チェック</b><div class="checklist mt16">${t.packing?.length?t.packing.map(p=>`<div class="row between"><label class="grow ${p.done?'done':''}"><input type="checkbox" data-check="packing" data-id="${esc(p.id)}" ${p.done?'checked':''}>${esc(p.text)}</label><button class="btn btn-ghost btn-sm" title="削除" data-act="delete-packing" data-id="${esc(p.id)}">✕</button></div>`).join(''):`<p class="small muted">必要なものを登録しておきましょう。</p>`}</div></div><div class="panel"><b>旅のメモ</b><p class="wide-info small mt16">${esc(t.lodging||'宿泊先・集合場所・予約情報などを、旅の設定から登録できます。')}</p><button class="btn btn-ghost btn-sm mt16" data-act="edit-trip">旅の情報を編集 →</button></div></div>`;}
function sharesOf(ex,t){const arr=Array.isArray(ex.shares)?ex.shares:[];if(arr.length)return arr;const ids=t.members.map(m=>m.id);if(!ids.length)return [];const base=Math.floor(Number(ex.amount||0)/ids.length);let remainder=Number(ex.amount||0)-base*ids.length;return ids.map(id=>({memberId:id,amount:base+(remainder-->0?1:0)}));}
function balanceData(t){const b=Object.fromEntries(t.members.map(m=>[m.id,0]));for(const e of t.expenses){if(b[e.payerId]!==undefined)b[e.payerId]+=Number(e.amount)||0;for(const s of sharesOf(e,t)){if(b[s.memberId]!==undefined)b[s.memberId]-=Number(s.amount)||0;}}for(const x of(t.transfers||[])){if(b[x.from]!==undefined)b[x.from]+=Number(x.amount)||0;if(b[x.to]!==undefined)b[x.to]-=Number(x.amount)||0;}return b;}
function settlements(t){let balances=balanceData(t);const debtors=Object.entries(balances).filter(([,v])=>v<-.001).map(([id,v])=>({id,amount:-v})).sort((a,b)=>b.amount-a.amount);const creditors=Object.entries(balances).filter(([,v])=>v>.001).map(([id,v])=>({id,amount:v})).sort((a,b)=>b.amount-a.amount);let result=[],i=0,j=0;while(i<debtors.length&&j<creditors.length){const amount=Math.min(debtors[i].amount,creditors[j].amount);if(amount>=1)result.push({from:debtors[i].id,to:creditors[j].id,amount:Math.round(amount)});debtors[i].amount-=amount;creditors[j].amount-=amount;if(debtors[i].amount<.5)i++;if(creditors[j].amount<.5)j++;}return result;}
function memberName(t,id){return t.members.find(m=>m.id===id)?.name||'不明';}
function renderCosts(t){const actual=sum(t.expenses,'amount'),planned=sum(t.schedules,'planCost'),remaining=t.budget-actual;const b=balanceData(t),settle=settlements(t);return `${heading('TRAVEL BUDGET','旅のお金','予算・実績・立替精算をまとめて管理します。',`<button class="btn btn-primary btn-sm" data-act="new-expense">＋ 支出を記録</button>`)}${tripBanner(t)}<div class="grid3"><div class="kpi"><div class="label">旅行の予算</div><div class="num">${yen(t.budget)}</div><div class="aside">${t.budget?'設定した予算':'旅の設定で登録できます'}</div></div><div class="kpi"><div class="label">実際の支出</div><div class="num">${yen(actual)}</div><div class="aside">${t.expenses.length}件の支出</div></div><div class="kpi"><div class="label">予算残額</div><div class="num" style="color:${remaining<0?'#b36247':'var(--forest)'}">${yen(remaining)}</div><div class="aside">旅程の予定費用 ${yen(planned)}</div></div></div><div class="section-header"><h2 class="section-title">支出の記録</h2><button class="btn btn-primary btn-sm" data-act="new-expense">＋ 追加</button></div>${t.expenses.length?`<div class="bill-list">${t.expenses.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(e=>`<div class="bill-row"><div class="bill-icon">${catIcons[e.category]||'🧾'}</div><div class="grow"><div class="bill-name">${esc(e.title)}</div><div class="bill-meta">${esc(dateFmt(e.date))} ・ 支払者：${esc(memberName(t,e.payerId))} ・ ${esc(e.category)}</div><button class="btn btn-ghost btn-sm mt8" data-act="edit-expense" data-id="${esc(e.id)}">編集</button></div><div class="bill-price">${yen(e.amount)}</div></div>`).join('')}</div>`:`<div class="empty"><div class="empty-art">🧾</div><h3>旅行の支出を記録しましょう</h3><p>支払った人と負担する人を選ぶだけで、精算額を計算します。</p><button class="btn btn-primary" data-act="new-expense">＋ 支出を追加</button></div>`}<div class="section-header"><h2 class="section-title">メンバー別の精算</h2><span class="section-sub">立替残高</span></div><div class="grid2"><div class="panel"><div class="eyebrow">BALANCES</div><table class="split-table"><thead><tr><th>参加者</th><th>受取・支払残額</th></tr></thead><tbody>${t.members.map(m=>`<tr><td>${esc(m.name)}</td><td class="${b[m.id]>=0?'balance-plus':'balance-minus'}">${b[m.id]>0?'+':''}${yen(b[m.id])}</td></tr>`).join('')}</tbody></table><p class="form-help mt16">＋は受け取り予定、−は支払い予定です。実際に精算した金額も反映します。</p></div><div class="panel"><div class="eyebrow">SETTLEMENTS</div><h3 style="margin:9px 0 17px">おすすめの精算方法</h3>${settle.length?settle.map((x,i)=>`<div class="row between" style="padding:10px 0;border-bottom:1px solid var(--line)"><div class="grow small"><b>${esc(memberName(t,x.from))}</b> → <b>${esc(memberName(t,x.to))}</b><div class="muted mt8">${yen(x.amount)} 支払う</div></div><button class="btn btn-secondary btn-sm" data-act="pay" data-from="${esc(x.from)}" data-to="${esc(x.to)}" data-amount="${x.amount}">精算済みにする</button></div>`).join(''):`<div class="tip-line"><span class="symbol">✓</span><span>現在、追加で必要な精算はありません。</span></div>`}</div></div>${t.transfers?.length?`<div class="section-header"><h2 class="section-title">精算履歴</h2></div><div class="panel stack">${t.transfers.map(x=>`<div class="row between"><div class="small">${esc(memberName(t,x.from))} → ${esc(memberName(t,x.to))}　<b>${yen(x.amount)}</b><div class="muted">${esc(dateFmt(x.date))} に精算</div></div><button class="btn btn-ghost btn-sm" data-act="undo-pay" data-id="${esc(x.id)}">取り消す</button></div>`).join('')}</div>`:''}<div class="notice mt24">費用は整数の円で計算し、端数は自動配分します。「予定費用」は予算の参考値で、支出実績には自動計上しません。</div>`;}
function mapConfig(t,idx){return t.maps?.pages?.[String(idx)]||{};}
function mapItems(t){return orderSched(t).filter(s=>s.showBoard!==false);}
function boardPageCount(t){return Math.max(1,Math.ceil(mapItems(t).length/PAGE_SIZE));}
function boardEntries(t,idx){return mapItems(t).slice(idx*PAGE_SIZE,(idx+1)*PAGE_SIZE);}
function boardPath(idx,total,points){
  if(!points.length)return '';
  // 上下の接合点はどのページでも横50%。同じX座標から次ページの道が続く。
  const route=[...(idx>0?[[50,100]]:[]),...points,...(idx<total-1?[[50,0]]:[])];
  return route.length>1?'M '+route.map(([x,y])=>`${x*10.8} ${y*19.2}`).join(' L '):'';
}
function mapPrompt(t,idx){
  const items=boardEntries(t,idx),temp=boardTemplate(idx),total=boardPageCount(t);
  const slots=temp.points.slice(0,items.length);
  const left=slots.filter(([x])=>x<50).length,right=slots.length-left;
  const rows=['下部（最も下）','下寄り','縦中央','上寄り','上部（最も上）'];
  const positions=slots.map(([x,y],i)=>`${rows[i]}・${x<50?'左':'右'}（上から約${y}%）：${items[i].name}${items[i].place?'（'+items[i].place+'）':''}`);
  return `スマートフォン縦向き9:16（1080×1920pxを目安）の、16-bit RPGゲーム風ピクセルアートの背景画像を1枚作成してください。

【旅行】${t.title}
【行き先】${t.destination||'日本の旅行'}
【ページ】${idx+1} / ${total}（${temp.name}）

【最重要：観光地の配置】
${items.length?`画像の${slots[0][0]<50?'左':'右'}下からスタートし、旅の順に左右交互に、等間隔で上へ進む構図です。左側に${left}か所、右側に${right}か所の目的地を描きます。
${positions.join('\n')}
上記は下から上へ進む旅の順番です。下端をスタート側とし、上下や左右を反転しないでください。
各目的地のイメージは指定された高さ・左右の側に一つずつ描き、別の目的地と入れ替えないでください。`:'目的地の指定はありません。地域の景観だけを描いてください。'}

【描き方】
各観光地を象徴する建物・自然・植物などを指定の位置の近くに、小さめのランドマークとして描いてください。左側のマスは画像の左から約24%、右側のマスは約76%の位置に重なります。マス中心と周囲のラベルが載る部分は平坦な草地などにして、ランドマークの主役は同じ高さで少し中央寄り、またはすぐ横にずらしてください。地形は自然につなげ、温かく色彩豊かな日本製レトロRPGの俯瞰ワールドマップ風にします。

【ページのつながり】
マップは上下に連結し、次のページは現在のページの上に続きます。${idx>0?'下端の中央は前ページからの入口です。':'このページの下側は旅の始まりです。'}${idx<total-1?'上端の中央は次ページへの出口です。':'このページが旅の最後です。'} 接続する上下端の中央付近は穏やかな地形とし、左右には接続しません。

【出力規則】
背景の風景だけを描いてください。文字、数字、マス、経路線、矢印、道路線、地図ピン、ロゴ、UI、枠線は一切描かないでください。道・マス・ラベルはアプリが後から合成します。普通の縦長9:16を保ち、余白も美しく、全ページで同じ画風にしてください。`;
}
function renderBoardPage(t,idx,total,entries){
  const temp=boardTemplate(idx),pts=temp.points.slice(0,entries.length),path=boardPath(idx,total,pts),backdrop=imageSrc(mapConfig(t,idx).background);
  return `<section class="map-sheet" data-map-page="${idx}" aria-label="第${idx+1}ページ ${temp.name}">
    <div class="map-landscape"></div>
    ${backdrop?`<img class="map-background" src="${backdrop}" alt="第${idx+1}ページのすごろく背景" draggable="false">`:`<div class="map-world-art"><span class="pixel-cloud" style="top:10%;left:10%">☁</span><span class="pixel-cloud" style="top:19%;right:7%">☁</span><span class="pixel-spot" style="top:24%;left:11%">🏔️</span><span class="pixel-spot" style="top:38%;right:5%">🌲</span><span class="pixel-spot" style="bottom:16%;left:7%">🌻</span><span class="pixel-spot" style="bottom:27%;right:14%">🏡</span><span class="pixel-spot" style="top:56%;left:17%">🌳</span></div>`}
    <div class="map-dim"></div>
    <svg viewBox="0 0 1080 1920" preserveAspectRatio="none" class="map-path" aria-hidden="true">${path?`<path class="path-base" d="${path}"/><path class="path-dashes" d="${path}"/>`:''}</svg>
    ${entries.map((s,i)=>{const [x,y]=pts[i];return `<button class="map-node ${s.status==='visited'?'visited':s.status==='current'?'current':''} ${y<25?'toplabel':''}" style="left:${x}%;top:${y}%" data-act="map-spot" data-id="${esc(s.id)}" aria-label="${esc(s.name)}">${s.status==='visited'?'✓':idx*PAGE_SIZE+i+1}<span class="node-label">${esc(s.time)} ${esc(s.name)}</span></button>`;}).join('')}
    ${idx===0&&entries.length?`<div class="map-endpoint start" style="left:${pts[0][0]}%">${total===1&&entries.length===1?'START / GOAL':'START'}</div>`:''}
    ${idx===total-1&&entries.length&&!(total===1&&entries.length===1)?`<div class="map-endpoint goal ${pts.at(-1)[1]<25?'goal-below':''}" style="left:${pts.at(-1)[0]}%;top:${pts.at(-1)[1]}%">GOAL</div>`:''}
    ${!entries.length?'<div class="map-empty-message">しおりに予定を登録すると<br>旅の道が現れます。</div>':''}
  </section>`;
}
function renderBoardControls(t,idx,total){return `<button class="btn btn-ghost" data-act="map-prev" ${idx===0?'disabled':''}>↓ 前のページ</button><span class="counter">${idx+1} / ${total}</span><button class="btn btn-ghost" data-act="map-next" ${idx===total-1?'disabled':''}>次のページ ↑</button>`;}
function renderBoardHeader(t,idx,total){return `✦ ${esc(t.destination||'旅の冒険')} ✦<small>CHAPTER ${String(idx+1).padStart(2,'0')} ・ ${esc(boardTemplate(idx).name)} ・ ${boardEntries(t,idx).length} SPOTS</small>`;}
function renderBoardSidebar(t,idx){
  const entries=boardEntries(t,idx),temp=boardTemplate(idx),conf=mapConfig(t,idx),backdrop=imageSrc(conf.background);
  return `<div class="panel"><div class="eyebrow">BOARD DESIGN</div><h2 class="section-title mt8">マップを飾る</h2><p class="small muted mt8" style="line-height:1.7">奇数ページは左下、偶数ページは右下から始まります。最大5マスずつ、下から上へ自動配置します。</p><div class="tip-line mt16"><span class="symbol">↟</span><span><b>第${idx+1}ページ：${esc(temp.name)}</b><br><span class="small muted">${idx%2===0?'左 → 右 → 左 → 右 → 左':'右 → 左 → 右 → 左 → 右'}（下から上）</span></span></div>
    ${backdrop&&conf.layoutVersion!==BOARD_LAYOUT_VERSION?`<div class="notice mt16">旧レイアウトで登録された背景画像です。画像は残しています。新しいプロンプトで生成し直すと、新しいマス配置に合わせられます。</div>`:''}
    <div class="map-extra mt16"><button class="btn btn-primary btn-sm" data-act="map-prompt">✦ AI画像用プロンプト</button><button class="btn btn-secondary btn-sm" data-act="map-bg">↑ 背景画像を登録</button>${backdrop?`<button class="btn btn-ghost btn-sm" data-act="map-bg-clear">背景を解除</button>`:''}</div></div>
    <div class="panel"><div class="eyebrow">ADVENTURE LOG</div><h2 class="section-title mt8">このページの訪問先</h2><div class="map-locations mt16">${entries.length?entries.map((s,i)=>`<button class="map-place" data-act="map-spot" data-id="${esc(s.id)}"><span class="number">${idx*PAGE_SIZE+i+1}</span><div class="grow"><div class="title truncate">${esc(s.name)}</div><div class="time">${esc(s.date)} ${esc(s.time)}・${esc(s.place||s.category)}</div></div><span>${s.status==='visited'?'✅':'›'}</span></button>`).join(''):`<p class="small muted">しおりに予定を追加すると、ここにマスが表示されます。</p>`}</div></div><div class="notice">背景画像はChatGPTなどで作成して取り込みます。マス・文字・道はアプリが重ねます。</div>`;
}
function renderBoard(t){
  const items=mapItems(t),total=Math.max(1,Math.ceil(items.length/PAGE_SIZE));
  ui.mapPage=Math.max(0,Math.min(total-1,ui.mapPage));const idx=ui.mapPage;
  // 上から最終ページ、…、第1ページ。実際に隙間なく上下に積み重ねる。
  const pages=Array.from({length:total},(_,i)=>total-1-i).map(i=>renderBoardPage(t,i,total,items.slice(i*PAGE_SIZE,(i+1)*PAGE_SIZE))).join('');
  return `${heading('RPG TRAVEL BOARD','旅のすごろく','一歩ずつ上へ。旅の予定が、つながる冒険マップになります。')}${tripBanner(t)}<div class="map-layout"><div class="map-column"><div id="map-header" class="map-heading-band">${renderBoardHeader(t,idx,total)}</div><div class="map-frame vertical-frame"><div id="map-stage" class="map-scroll" tabindex="0" aria-label="上下につながるすごろく。指で下にスワイプすると上の次ページへ移動します。">${pages}</div></div><div class="map-controls" id="map-controls">${renderBoardControls(t,idx,total)}</div><p class="map-tip">マップを指で下へ引くと上の次ページ、上へ引くと前ページ。<br>マスをタップして詳細表示。ボタンでも移動できます。</p></div><div class="map-side" id="map-side">${renderBoardSidebar(t,idx)}</div></div>`;
}
function updateBoardPanels(t,idx){
  if(ui.screen!=='board'||current()?.id!==t.id)return;
  ui.mapPage=idx;const total=boardPageCount(t);
  $('#map-header').innerHTML=renderBoardHeader(t,idx,total);
  $('#map-controls').innerHTML=renderBoardControls(t,idx,total);
  $('#map-side').innerHTML=renderBoardSidebar(t,idx);
}
function bindBoardViewport(t){
  const stage=$('#map-stage');if(!stage)return;
  const sheet=stage.querySelector(`[data-map-page="${ui.mapPage}"]`);if(sheet)stage.scrollTop=sheet.offsetTop;
  let timer;
  stage.addEventListener('scroll',()=>{clearTimeout(timer);timer=setTimeout(()=>{
    if(!stage.isConnected||!stage.clientHeight)return;
    const sheets=[...stage.querySelectorAll('.map-sheet')];
    const nearest=sheets.reduce((a,b)=>Math.abs(b.offsetTop-stage.scrollTop)<Math.abs(a.offsetTop-stage.scrollTop)?b:a);
    const idx=Number(nearest.dataset.mapPage);if(idx!==ui.mapPage)updateBoardPanels(t,idx);
  },90);},{passive:true});
  stage.addEventListener('keydown',e=>{if(e.target!==stage)return;if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();moveBoardPage(e.key==='ArrowUp'?1:-1);}});
}
function moveBoardPage(delta){
  const t=current(),stage=$('#map-stage');if(!t||!stage)return;
  const idx=Math.max(0,Math.min(boardPageCount(t)-1,ui.mapPage+delta));
  if(idx===ui.mapPage)return;
  const sheet=stage.querySelector(`[data-map-page="${idx}"]`);if(!sheet)return;
  stage.scrollTop=sheet.offsetTop;updateBoardPanels(t,idx);
}
function renderAlbum(t){return `${heading('MEMORY SCRAPBOOK','旅のアルバム','写真と思い出を残して、自分だけのスクラップブックを作りましょう。',`<button class="btn btn-secondary btn-sm" data-act="pdf-album">↓ A4 PDF</button><button class="btn btn-primary btn-sm" data-act="new-photo">＋ 写真</button>`)}${tripBanner(t)}${t.photos.length?`<div class="row between mb12"><div class="section-title">旅の記憶 <span class="small muted">${t.photos.length}枚</span></div><span class="small muted">写真をタップして編集</span></div><div class="album-grid">${t.photos.slice().sort((a,b)=>(a.date||'').localeCompare(b.date||'')).map(p=>`<button class="album-tile" data-act="edit-photo" data-id="${esc(p.id)}"><img src="${imageSrc(p.data)}" alt="${esc(p.title)}"><div class="caption truncate">${esc(p.title||'旅のひとこま')}</div><div class="subcaption">${esc(dateFmt(p.date))}</div></button>`).join('')}</div>`:`<div class="empty"><div class="empty-art">📷</div><h3>旅の思い出を貼りましょう</h3><p>写真と一言を残すだけで、スクラップブックが育っていきます。<br>旅程の予定とも紐づけられます。</p><button class="btn btn-primary" data-act="new-photo">＋ 写真を追加</button></div>`}<div class="tip-line mt24"><span class="symbol">📚</span><div>登録した写真はスクラップブック形式のA4縦PDFにできます。画像は端末内に保存されるため、機種変更前にはバックアップを作成してください。</div></div>`;}
function renderSettings(t){return `${heading('SETTINGS & DATA','設定・バックアップ','旅行の設定、参加者、保存データを管理します。')}${t?`${tripBanner(t)}<div class="grid2"><div class="panel"><div class="eyebrow">JOURNEY</div><h2 class="section-title mt8">旅行の基本情報</h2><div class="info-list mt16">${[['タイトル',t.title],['旅行期間',`${dateFmt(t.start)}〜${dateFmt(t.end)}`],['行き先',t.destination||'未設定'],['予算',yen(t.budget)]].map(([a,b])=>`<div class="info-line"><span>${esc(a)}</span><span>${esc(b)}</span></div>`).join('')}</div><button class="btn btn-secondary btn-sm mt16" data-act="edit-trip">編集する</button></div><div class="panel"><div class="eyebrow">MEMBERS</div><h2 class="section-title mt8">参加者</h2><div class="settings-list mt16">${t.members.map(m=>`<span class="member-chip">👤 ${esc(m.name)}</span>`).join('')}</div><button class="btn btn-secondary btn-sm mt16" data-act="members">参加者を管理する</button></div></div>`:needTrip()}<div class="section-header"><h2 class="section-title">データの保管</h2></div><div class="grid2"><div class="panel"><div style="font-size:26px">⬇️</div><h3 class="mt16">バックアップを保存</h3><p class="wide-info small">旅行・写真・費用・すごろく背景をまとめてJSONファイルで保存します。</p><button class="btn btn-primary btn-sm" data-act="backup">バックアップを作成</button></div><div class="panel"><div style="font-size:26px">⬆️</div><h3 class="mt16">バックアップを復元</h3><p class="wide-info small">以前の保存ファイルから復元できます。現在の旅行一覧を置き換えます。</p><button class="btn btn-secondary btn-sm" data-act="restore">ファイルを選択</button></div></div><div class="section-header"><h2 class="section-title">使い方と保存について</h2></div><div class="panel wide-info small"><b>GitHub Pagesで公開できます。</b> HTML・CSS・JavaScriptのみで動くため、サーバーや有料APIは必要ありません。HTTPS環境ではPWAとしてホーム画面に追加できます。<br><b>保存場所：</b>写真・予定などは利用中のブラウザのIndexedDBに保存します。ブラウザのデータ削除・端末変更・プライベートブラウズでは消える可能性があります。定期的にバックアップしてください。<br><b>PDF：</b>インターネット接続なしで作成します。ページ全体を画像として埋め込む方式のため、PDF内の文章はテキスト選択できません。<br><b>共有：</b>この初期版にはクラウド同期・共同編集機能はありません。${storageOk?'':'<br><b style="color:#aa4e37">注意：現在、ブラウザ保存を利用できません。</b>'}</div>${t?`<div class="section-header"><h2 class="section-title">旅行の削除</h2></div><div class="danger-zone"><b>この旅行を削除する</b><p class="small muted mt8">旅行に含まれる予定・写真・費用・すごろく背景もすべて削除されます。</p><button class="btn btn-danger btn-sm" data-act="delete-trip">旅行を削除</button></div>`:''}`;}
function render(){renderNavigation();renderTop();const t=current();const view=$('#view');if(!t&&ui.screen!=='home'&&ui.screen!=='settings'){view.innerHTML=heading('START HERE','旅をはじめよう','まず旅行を作成してください。')+needTrip();return;}if(ui.screen==='home')view.innerHTML=renderHome();else if(ui.screen==='schedule')view.innerHTML=renderSchedule(t);else if(ui.screen==='board'){view.innerHTML=renderBoard(t);bindBoardViewport(t);}else if(ui.screen==='costs')view.innerHTML=renderCosts(t);else if(ui.screen==='album')view.innerHTML=renderAlbum(t);else if(ui.screen==='settings')view.innerHTML=renderSettings(t);}
function tripModal(edit=false){let t=edit?current():null;const start=t?.start||today();const body=`<form id="trip-form"><div class="form-grid">${field('旅行のタイトル','title','text',t?.title||'',{required:true,span:true,attrs:'maxlength="100" placeholder="例：北海道を巡る3日間"'})}${field('出発日','start','date',start,{required:true})}${field('帰着日','end','date',t?.end||start,{required:true})}${field('旅行先・地域','destination','text',t?.destination||'',{span:true,attrs:'placeholder="例：札幌・小樽・ニセコ"'})}${field('全体予算（円）','budget','number',t?.budget||0,{min:0,attrs:'step="1"'})}${field('宿泊先・緊急連絡先など','lodging','text',t?.lodging||'')}${textarea('旅のテーマ・メモ','description',t?.description||'')}<div class="form-field span2"><label>表紙写真（任意）</label>${imageSrc(t?.cover)?`<img class="preview-image" src="${imageSrc(t.cover)}" alt="現在の表紙">`:''}<input class="input-file" type="file" name="cover" accept="image/*"><div class="form-help">画像は自動的に縮小して端末内に保存します。</div></div></div>${buttons(edit?'変更を保存':'旅を作成')}</form>`;showDialog(edit?'旅の基本情報を編集':'新しい旅を作成',body);bindForm('trip-form',async(f,form)=>{const title=String(f.get('title')||'').trim(),start=String(f.get('start')),end=String(f.get('end'));if(!title)throw Error('旅行タイトルを入力してください。');if(end<start)throw Error('帰着日は出発日以降にしてください。');if(dateRange(start,end).length>=80)throw Error('日程は79日以内にしてください。');if(edit){t.title=title;t.start=start;t.end=end;t.destination=String(f.get('destination')||'');t.budget=Math.max(0,Math.round(Number(f.get('budget'))||0));t.lodging=String(f.get('lodging')||'');t.description=String(f.get('description')||'');if(form.elements.cover.files[0])t.cover=await compress(form.elements.cover.files[0]);}else{t=newTrip({title,start,end,destination:String(f.get('destination')||''),budget:Number(f.get('budget'))||0,lodging:String(f.get('lodging')||''),description:String(f.get('description')||'')});if(form.elements.cover.files[0])t.cover=await compress(form.elements.cover.files[0]);state.trips.push(t);ui.tripId=t.id;ui.day=t.start;ui.mapPage=0;ui.screen='schedule';window.scrollTo(0,0);}closeDialog();changed(edit?'旅の設定を更新しました。':'新しい旅を作成しました。');});}
function scheduleModal(id){const t=current(),s=t.schedules.find(x=>x.id===id)||null;const day=selectedDay(t);const body=`<form id="schedule-form"><div class="form-grid">${field('予定名','name','text',s?.name||'',{required:true,span:true,attrs:'maxlength="120" placeholder="例：札幌時計台へ行く"'})}${field('日付','date','date',s?.date||day,{required:true})}${selectField('カテゴリー','category',categories,s?.category||'観光')}${field('開始時刻','time','time',s?.time||'09:00',{required:true})}${field('終了時刻（任意）','endTime','time',s?.endTime||'')}${field('場所・施設名','place','text',s?.place||'',{span:true,attrs:'placeholder="例：札幌時計台"'})}${field('住所','address','text',s?.address||'',{span:true})}${field('予定費用（円）','planCost','number',s?.planCost||0,{min:0,attrs:'step="1"'})}${selectField('訪問状況','status',['未訪問','訪問中','訪問済み','スキップ'],s?({pending:'未訪問',current:'訪問中',visited:'訪問済み',skipped:'スキップ'}[s.status]||'未訪問'):'未訪問')}${field('公式サイト・参考URL','url','url',s?.url||'',{span:true})}${textarea('メモ・予約情報','notes',s?.notes||'')}<div class="form-field span2"><label>しおりに載せる写真</label>${imageSrc(s?.photo)?`<img class="preview-image" src="${imageSrc(s.photo)}" alt="予定の写真">`:''}<input name="photo" type="file" accept="image/*" class="input-file"><label class="checkrow"><input type="checkbox" name="removePhoto" value="1">${s?'現在の写真を削除する':'写真なし'}</label><label class="checkrow"><input type="checkbox" name="showBoard" value="1" ${s?.showBoard===false?'':'checked'}>この予定をすごろくのマスに表示する</label></div></div>${buttons(s?'更新する':'予定を追加する',s?`<button type="button" class="btn btn-danger" data-act="delete-sched" data-id="${esc(s.id)}">削除</button>`:'')}</form>`;showDialog(s?'予定を編集':'予定を追加',body);bindForm('schedule-form',async(f,form)=>{if(String(f.get('date'))<t.start||String(f.get('date'))>t.end)throw Error('日付は旅行期間内を選んでください。');if(f.get('endTime')&&f.get('endTime')<f.get('time'))throw Error('終了時刻は開始時刻以降にしてください。');let photo=s?.photo||'';if(f.get('removePhoto'))photo='';if(form.elements.photo.files[0])photo=await compress(form.elements.photo.files[0]);const statuses={'未訪問':'pending','訪問中':'current','訪問済み':'visited','スキップ':'skipped'};const data={name:String(f.get('name')||'').trim(),date:String(f.get('date')),time:String(f.get('time')),endTime:String(f.get('endTime')),category:String(f.get('category')),place:String(f.get('place')||''),address:String(f.get('address')||''),url:String(f.get('url')||''),notes:String(f.get('notes')||''),planCost:Math.max(0,Math.round(Number(f.get('planCost'))||0)),status:statuses[String(f.get('status'))]||'pending',showBoard:!!f.get('showBoard'),photo};if(!data.name)throw Error('予定名を入力してください。');if(s)Object.assign(s,data);else t.schedules.push({id:uid(),...data});ui.day=data.date;closeDialog();changed(s?'予定を変更しました。':'予定を追加しました。');});}
function expenseModal(id){const t=current(),ex=t.expenses.find(x=>x.id===id)||null;const oldIds=ex?.shares?.map(s=>s.memberId)||t.members.map(m=>m.id);const baseShares=Object.fromEntries((ex?.shares||[]).map(s=>[s.memberId,s.amount]));const method=ex?.method||'equal';const body=`<form id="expense-form"><div class="form-grid">${field('支出内容','title','text',ex?.title||'',{span:true,required:true,attrs:'placeholder="例：レンタカー代"'})}${field('金額（円）','amount','number',ex?.amount||'',{required:true,min:1,attrs:'step="1"'})}${field('支出日','date','date',ex?.date||selectedDay(t),{required:true})}${selectField('カテゴリー','category',feeCategories,ex?.category||'食費')}${`<div class="form-field"><label for="payer">支払った人</label><select id="payer" name="payerId">${t.members.map(m=>`<option value="${esc(m.id)}" ${m.id===(ex?.payerId||t.members[0]?.id)?'selected':''}>${esc(m.name)}</option>`).join('')}</select></div>`}${textarea('メモ','memo',ex?.memo||'')}<div class="form-field span2"><label>負担する人（割り勘対象）</label><div class="members-box">${t.members.map(m=>`<label class="member-option checkrow"><input type="checkbox" name="shares" value="${esc(m.id)}" ${oldIds.includes(m.id)?'checked':''}>${esc(m.name)}</label>`).join('')}</div></div>${selectField('分配方法','method',['均等割り','金額を指定'],method==='custom'?'金額を指定':'均等割り',true)}<div class="form-field span2 ${method==='custom'?'':'hidden'}" id="split-custom"><label>各参加者の負担額（合計が支出額になるように入力）</label>${t.members.map(m=>`<label class="row between small" style="margin-bottom:8px">${esc(m.name)}<input class="input" style="max-width:145px" type="number" min="0" step="1" name="share-${esc(m.id)}" value="${baseShares[m.id]||0}"></label>`).join('')}<div class="form-help">均等割りの場合は端数を自動処理します。</div></div></div>${buttons(ex?'支出を更新':'支出を追加',ex?`<button type="button" class="btn btn-danger" data-act="delete-expense" data-id="${esc(ex.id)}">削除</button>`:'')}</form>`;showDialog(ex?'支出を編集':'支出を記録',body);const f=$('#expense-form');f.elements.method.addEventListener('change',()=>$('#split-custom').classList.toggle('hidden',f.elements.method.value!=='金額を指定'));bindForm('expense-form',async(d)=>{const amount=Number(d.get('amount'));if(!Number.isSafeInteger(amount)||amount<=0)throw Error('金額は1円以上の整数で入力してください。');const selected=d.getAll('shares').map(String);if(!selected.length)throw Error('負担する人を1名以上選んでください。');let shares;if(d.get('method')==='金額を指定'){shares=selected.map(id=>({memberId:id,amount:Number(d.get('share-'+id))||0}));if(shares.some(s=>!Number.isSafeInteger(s.amount)||s.amount<0)||shares.reduce((n,s)=>n+s.amount,0)!==amount)throw Error('個別の負担額の合計を支出金額と一致させてください。');}else{const base=Math.floor(amount/selected.length);let remainder=amount-base*selected.length;shares=selected.map(id=>({memberId:id,amount:base+(remainder-->0?1:0)}));}const result={title:String(d.get('title')||'').trim(),amount,date:String(d.get('date')),payerId:String(d.get('payerId')),category:String(d.get('category')),method:d.get('method')==='金額を指定'?'custom':'equal',shares,memo:String(d.get('memo')||'')};if(!result.title)throw Error('支出内容を入力してください。');if(ex)Object.assign(ex,result);else t.expenses.push({id:uid(),...result});closeDialog();changed(ex?'支出を変更しました。':'支出を記録しました。');});}
function photoModal(id){const t=current(),p=t.photos.find(x=>x.id===id)||null;const body=`<form id="photo-form"><div class="form-grid">${field('写真タイトル','title','text',p?.title||'',{span:true,attrs:'placeholder="例：小樽運河の夕暮れ"'})}${field('撮影日','date','date',p?.date||selectedDay(t),{required:true})}<div class="form-field"><label for="photo-linked">関連する予定</label><select id="photo-linked" name="scheduleId"><option value="">特に指定しない</option>${orderSched(t).map(s=>`<option value="${esc(s.id)}" ${p?.scheduleId===s.id?'selected':''}>${esc(s.date.slice(5))} ${esc(s.name)}</option>`).join('')}</select></div>${textarea('思い出・コメント','caption',p?.caption||'')}<div class="form-field span2"><label>写真 ${p?'（変更するときだけ選択）':'（必須）'}</label>${p?`<img class="preview-image" src="${imageSrc(p.data)}" alt="登録済みの写真">`:''}<input type="file" name="file" accept="image/*" class="input-file" ${p?'':'required'}></div></div>${buttons(p?'写真を更新':'写真を追加',p?`<button type="button" class="btn btn-danger" data-act="delete-photo" data-id="${esc(p.id)}">削除</button>`:'')}</form>`;showDialog(p?'思い出を編集':'写真を追加',body);bindForm('photo-form',async(d,form)=>{let data=p?.data||'';if(form.elements.file.files[0])data=await compress(form.elements.file.files[0],1700,.85);if(!data)throw Error('写真を選択してください。');const scheduleId=String(d.get('scheduleId')||'');const record={title:String(d.get('title')||'').trim()||t.schedules.find(s=>s.id===scheduleId)?.name||'旅のひとこま',date:String(d.get('date')),caption:String(d.get('caption')||''),scheduleId,data};if(p)Object.assign(p,record);else t.photos.push({id:uid(),...record});closeDialog();changed(p?'写真を変更しました。':'思い出の写真を追加しました。');});}
function mapSpotModal(id){const t=current(),s=t.schedules.find(a=>a.id===id);if(!s)return;const html=`<div class="stack"><span class="tag">${esc(s.date)}　${esc(s.time)}　${esc(s.category)}</span>${imageSrc(s.photo)?`<img src="${imageSrc(s.photo)}" alt="${esc(s.name)}" style="width:100%;height:185px;object-fit:cover;border-radius:14px">`:''}<h3 class="section-title">${esc(s.name)}</h3><p class="wide-info">${esc(s.place||'')}<br>${esc(s.notes||'')}</p>${s.address||s.place?`<a class="btn btn-ghost btn-sm" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(s.address||s.place)}" target="_blank" rel="noopener noreferrer">📍 地図で見る</a>`:''}<div class="btn-row"><button class="btn btn-secondary" data-act="map-visit" data-id="${esc(s.id)}">${s.status==='visited'?'↩ 未訪問に戻す':'✓ 訪問済みにする'}</button><button class="btn btn-ghost" data-act="edit-sched" data-id="${esc(s.id)}">予定を編集</button></div></div>`;showDialog('冒険のチェックポイント',html);}
function backgroundModal(){const t=current(),idx=ui.mapPage,old=mapConfig(t,idx).background;showDialog('すごろくの背景画像',`<form id="bg-form"><p class="wide-info small">ChatGPTなどで作成した縦長9:16の背景画像を取り込みます。マスと文字は自動で上に重なります。9:16以外の画像は全体を縦長枠に合わせて表示します。</p>${old?`<img class="preview-image" src="${imageSrc(old)}" alt="現在の背景">`:''}<div class="form-field mt16"><label>背景画像</label><input name="bg" class="input-file" type="file" accept="image/*" required></div>${buttons('背景として登録')}</form>`);bindForm('bg-form',async(d,f)=>{let img=await compress(f.elements.bg.files[0],1920,.88);t.maps.pages[String(idx)]={...mapConfig(t,idx),background:img,layoutVersion:BOARD_LAYOUT_VERSION};closeDialog();changed('背景画像を登録しました。');});}
function promptModal(){let t=current(),prompt=mapPrompt(t,ui.mapPage);showDialog('AI画像生成プロンプト',`<p class="wide-info small">これをコピーしてChatGPTなどの画像生成に使ってください。目的地の上下・左右の配置と、上下のページ接続を自動で書き出しています。</p><textarea id="map-prompt-text" class="input" style="height:390px;min-height:390px;line-height:1.7;resize:vertical">${esc(prompt)}</textarea><div class="dialog-actions"><button class="btn btn-ghost" data-act="close-dialog">閉じる</button><button class="btn btn-primary" data-act="copy-prompt">コピーする</button></div>`);}
function membersModal(){let t=current();showDialog('旅のメンバー',`<div class="stack">${t.members.map(m=>`<div class="row between" style="padding:12px;border:1px solid var(--line);border-radius:11px"><span>👤 <b>${esc(m.name)}</b></span><span class="btn-row"><button class="btn btn-ghost btn-sm" data-act="rename-member" data-id="${esc(m.id)}">名前変更</button><button class="btn btn-danger btn-sm" data-act="remove-member" data-id="${esc(m.id)}">削除</button></span></div>`).join('')}<button class="btn btn-primary" data-act="add-member">＋ 参加者を追加</button><p class="form-help">支出や精算履歴で使われている参加者は削除できません。</p></div>`);}
function nameModal(id){const t=current(),m=t.members.find(x=>x.id===id);showDialog(m?'参加者名を変更':'参加者を追加',`<form id="member-form"><div class="form-grid">${field('表示名','name','text',m?.name||'',{span:true,required:true,attrs:'maxlength="35"'})}</div>${buttons(m?'更新する':'追加する')}</form>`);bindForm('member-form',async(d)=>{let name=String(d.get('name')||'').trim();if(!name)throw Error('名前を入力してください。');if(m)m.name=name;else t.members.push({id:uid(),name,color:'#5e9987'});closeDialog();changed(m?'名前を変更しました。':'参加者を追加しました。');});}
function packingModal(){showDialog('持ち物を追加',`<form id="packing-form"><div class="form-grid">${field('持ち物','text','text','',{span:true,required:true,attrs:'placeholder="例：充電器"'})}</div>${buttons('追加')}</form>`);bindForm('packing-form',async(d)=>{current().packing.push({id:uid(),text:String(d.get('text')||'').trim(),done:false});closeDialog();changed('持ち物を追加しました。');});}
async function clipboard(text){try{await navigator.clipboard.writeText(text);toast('コピーしました。');}catch{const el=document.createElement('textarea');el.value=text;el.style.cssText='position:fixed;top:-9999px';document.body.append(el);el.select();try{document.execCommand('copy');toast('コピーしました。');}catch{toast('コピーできませんでした。文章を選択してコピーしてください。');}el.remove();}}
async function pdfExport(type){const t=current();if(!t)return;toast('PDFを作成しています…');await new Promise(r=>setTimeout(r,70));try{const blob=type==='album'?await scrapbookPDF(t):await itineraryPDF(t);download(blob,`${fileSafe(t.title)}_${type==='album'?'思い出アルバム':'旅のしおり'}.pdf`);toast('A4縦のPDFを作成しました。');}catch(err){console.error(err);toast('PDFの作成に失敗しました。画像の量を減らして再度お試しください。');}}
function backup(){const b=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});download(b,`旅の手帖_バックアップ_${today()}.json`);toast('バックアップファイルを保存しました。');}
function restore(){let inp=document.createElement('input');inp.type='file';inp.accept='.json,application/json';inp.style.display='none';document.body.append(inp);inp.onchange=async()=>{try{const f=inp.files[0];if(!f)return;if(f.size>110*1024*1024)throw Error('ファイルの容量が大きすぎます。');const parsed=JSON.parse(await f.text());if(!parsed||!Array.isArray(parsed.trips)||!parsed.trips.every(t=>t.id&&Array.isArray(t.schedules)&&Array.isArray(t.members)&&Array.isArray(t.expenses)&&Array.isArray(t.photos)))throw Error('旅の手帖のバックアップ形式ではありません。');if(!confirm('現在保存されている全ての旅行を、バックアップの内容で置き換えます。よろしいですか？'))return;state={version:1,trips:parsed.trips.map(t=>({...t,packing:t.packing||[],transfers:t.transfers||[],maps:{pages:t.maps?.pages||{}}}))};ui.tripId=state.trips[0]?.id||null;ui.day=current()?.start||today();ui.screen='home';changed('バックアップを復元しました。');}catch(err){console.error(err);toast(err.message||'バックアップを読み込めませんでした。');}finally{inp.remove();}};inp.click();}
function handleAction(a,el){const t=current(),id=el.dataset.id;switch(a){
case 'nav':if(el.dataset.screen==='home'||t||el.dataset.screen==='settings')goto(el.dataset.screen);else goto(el.dataset.screen);break;
case 'new-trip':tripModal(false);break;
case 'edit-trip':if(t)tripModal(true);break;
case 'open-trip':choose(id);break;
case 'close-dialog':closeDialog();break;
case 'sample':{const demo=sample();state.trips.push(demo);ui.tripId=demo.id;ui.day=demo.start;ui.mapPage=0;ui.screen='schedule';window.scrollTo(0,0);changed('サンプル旅行を追加しました。');break;}
case 'day':ui.day=el.dataset.date;render();break;
case 'new-sched':scheduleModal();break;
case 'edit-sched':scheduleModal(id);break;
case 'delete-sched':{if(!confirm('この予定を削除しますか？ 関連付けたアルバム写真は残ります。'))return;t.schedules=t.schedules.filter(s=>s.id!==id);t.photos.forEach(p=>{if(p.scheduleId===id)p.scheduleId='';});closeDialog();changed('予定を削除しました。');break;}
case 'new-expense':expenseModal();break;
case 'edit-expense':expenseModal(id);break;
case 'delete-expense':if(confirm('この支出を削除しますか？')){t.expenses=t.expenses.filter(e=>e.id!==id);closeDialog();changed('支出を削除しました。');}break;
case 'pay':{const from=el.dataset.from,to=el.dataset.to,amount=Number(el.dataset.amount);if(!confirm(`${memberName(t,from)} さんが ${memberName(t,to)} さんに ${yen(amount)} を支払ったことを記録しますか？`))return;t.transfers.push({id:uid(),from,to,amount,date:today()});changed('精算を記録しました。');break;}
case 'undo-pay':if(confirm('この精算履歴を取り消しますか？')){t.transfers=t.transfers.filter(x=>x.id!==id);changed('精算を取り消しました。');}break;
case 'new-photo':photoModal();break;
case 'edit-photo':photoModal(id);break;
case 'delete-photo':if(confirm('この写真をアルバムから削除しますか？')){t.photos=t.photos.filter(p=>p.id!==id);closeDialog();changed('写真を削除しました。');}break;
case 'map-next':moveBoardPage(1);break;
case 'map-prev':moveBoardPage(-1);break;
case 'map-spot':mapSpotModal(id);break;
case 'map-visit':{const s=t.schedules.find(x=>x.id===id);if(s){s.status=s.status==='visited'?'pending':'visited';closeDialog();changed('訪問状況を更新しました。');}break;}
case 'map-prompt':promptModal();break;
case 'copy-prompt':clipboard($('#map-prompt-text')?.value||'');break;
case 'map-bg':backgroundModal();break;
case 'map-bg-clear':if(confirm('このページの背景画像を解除しますか？')){t.maps.pages[String(ui.mapPage)]={...mapConfig(t,ui.mapPage),background:''};changed('背景画像を解除しました。');}break;
case 'pdf-itinerary':pdfExport('trip');break;
case 'pdf-album':pdfExport('album');break;
case 'add-packing':packingModal();break;
case 'delete-packing':t.packing=t.packing.filter(p=>p.id!==id);changed();break;
case 'members':membersModal();break;
case 'add-member':nameModal();break;
case 'rename-member':nameModal(id);break;
case 'remove-member':{if(t.members.length<=1){toast('参加者は最低1人必要です。');return;}const inUse=t.expenses.some(e=>e.payerId===id||e.shares?.some(s=>s.memberId===id))||t.transfers.some(x=>x.from===id||x.to===id);if(inUse){toast('支出または精算履歴に登録されている参加者は削除できません。');return;}if(confirm('参加者を削除しますか？')){t.members=t.members.filter(m=>m.id!==id);closeDialog();changed('参加者を削除しました。');}break;}
case 'backup':backup();break;
case 'restore':restore();break;
case 'delete-trip':if(confirm('旅行の予定・写真・費用をすべて削除します。元に戻せません。本当に削除しますか？')){state.trips=state.trips.filter(x=>x.id!==t.id);ui.tripId=state.trips[0]?.id||null;ui.screen='home';changed('旅行を削除しました。');}break;
}}
// クリック・キーボード操作、旅行切替えなどを一元管理。
document.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(el){if(el.tagName==='BUTTON')e.preventDefault();handleAction(el.dataset.act,el);}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role="button"][data-act]')){e.preventDefault();handleAction(e.target.dataset.act,e.target);}});
dialog.addEventListener('click',e=>{if(e.target===dialog)closeDialog();});
document.addEventListener('change',e=>{const target=e.target;if(target.id==='trip-switch'){if(target.value)choose(target.value);else goto('home');}if(target.dataset.check==='packing'){const p=current()?.packing.find(x=>x.id===target.dataset.id);if(p){p.done=target.checked;changed();}}});
(async()=>{await load();ui.tripId=state.trips[0]?.id||null;ui.day=current()?.start||today();render();if('serviceWorker'in navigator&&location.protocol==='https:'){navigator.serviceWorker.register('./sw.js').catch(e=>console.warn('PWA:',e));}})();
